1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface InsuredItem {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	/** A request to price a set of items. Becomes a policy the claims refer back to. */
28	export interface QuoteStep {
29	  op: "quote";
30	  items: InsuredItem[];
31	}
32	
33	/** A claim against an earlier quote step, identified by its index. */
34	export interface ClaimStep {
35	  op: "claim";
36	  policy: number;
37	  incident: Incident;
38	}
39	
40	/**
41	 * The two things a scenario can ask for. Discriminating on `op` lets the
42	 * compiler guarantee a claim has an incident and a quote has items, so
43	 * neither dispatch arm needs a non-null assertion or a defaulted field.
44	 */
45	export type Step = QuoteStep | ClaimStep;
46	
47	export interface QuoteResult {
48	  premium: number;
49	}
50	
51	export interface ClaimResult {
52	  payout: number;
53	  remainingCap: number;
54	}
55	
56	export type StepResult = QuoteResult | ClaimResult;
57	
58	export interface ScenarioResults {
59	  results: StepResult[];
60	}
61	
62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const PROCESSING_FEE = 5;
81	
82	const WHOLE_PERCENT = 100;
83	
84	/**
85	 * Adjusts an amount by a percentage. A positive percent is a surcharge, a
86	 * negative one a discount.
87	 *
88	 * Multiplying before dividing keeps the arithmetic exact. A 1.1 multiplier
89	 * would not: floating-point `100 * 1.1` is 110.00000000000001, which rounds
90	 * up to 111 and yields a 116 G premium instead of 115 G.
91	 */
92	const adjustByPercent = (amount: number, percent: number): number =>
93	  (amount * (WHOLE_PERCENT + percent)) / WHOLE_PERCENT;
94	
95	/** All rounding is in the MHPCO's favor — always up. */
96	const roundInMHPCOsFavor = Math.ceil;
97	
98	const BUILDING_BLOCK_SIZE = 3;
99	const BUILDING_BLOCK_PREMIUM = 60;
100	
101	/** Only items of one and the same kind group into a block. */
102	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
103	  first !== undefined && rest.every((item) => item.type === first.type);
104	
105	/**
106	 * How many flat-rate blocks this list forms. A mixed list forms none — only
107	 * alike items group — and so does any list too short to fill one block.
108	 */
109	const countCompleteBlocks = (items: InsuredItem[]): number =>
110	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
111	
112	const CURSED_SURCHARGE_PERCENT = 50;
113	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
114	const HIGH_ENCHANTMENT_LEVEL = 5;
115	
116	/** A risk rule contributes its percent only when the item trips it. */
117	const percentWhen = (applies: boolean, percent: number): number =>
118	  applies ? percent : 0;
119	
120	const isHighlyEnchanted = (item: InsuredItem): boolean =>
121	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
122	
123	/** Risk surcharges add to the base premium; they do not compound. */
124	const riskSurchargePercentFor = (item: InsuredItem): number =>
125	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
126	  percentWhen(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
127	
128	/** An item's list price with its own risk surcharges applied. */
129	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
130	  adjustByPercent(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
131	
132	/**
133	 * Prices an item list: alike items are grouped into building blocks sold at a
134	 * flat rate, and whatever is left over is priced item by item, each at its own
135	 * risk-adjusted premium.
136	 */
137	const priceItems = (items: InsuredItem[]): number => {
138	  const blocks = countCompleteBlocks(items);
139	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
140	
141	  return (
142	    blocks * BUILDING_BLOCK_PREMIUM +
143	    leftovers.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0)
144	  );
145	};
146	
147	/** Discounts are negative adjustments — long-standing customers pay 20% less. */
148	const LOYALTY_DISCOUNT_PERCENT = -20;
149	const LOYALTY_YEARS = 2;
150	const REPEAT_CONTRACT_DISCOUNT_PERCENT = -15;
151	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
152	
153	const isLongStanding = (customer: Customer): boolean =>
154	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
155	
156	/** The first contract is assessed; every later one earns a discount instead. */
157	const contractPercentFor = (isFirstContract: boolean): number =>
158	  isFirstContract
159	    ? FIRST_INSURANCE_SURCHARGE_PERCENT
160	    : REPEAT_CONTRACT_DISCOUNT_PERCENT;
161	
162	/**
163	 * The customer's own standing modifies the item price. Unlike the risk
164	 * surcharges, which add up before being applied once, these modifiers
165	 * COMPOUND: each applies to the result of the last. A 20% discount followed
166	 * by a 10% surcharge is 100 -> 80 -> 88, not 100 -> 90.
167	 */
168	const applyCustomerModifiers = (
169	  price: number,
170	  customer: Customer,
171	  isFirstContract: boolean,
172	): number => {
173	  const afterLoyalty = adjustByPercent(
174	    price,
175	    percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
176	  );
177	
178	  return adjustByPercent(afterLoyalty, contractPercentFor(isFirstContract));
179	};
180	
181	/**
182	 * The premium pipeline, in the order the spec states it: price the items,
183	 * apply the customer's modifiers, round, then add the processing fee last.
184	 */
185	const quotePremium = (
186	  items: InsuredItem[],
187	  customer: Customer,
188	  isFirstContract: boolean,
189	): QuoteResult => ({
190	  premium:
191	    roundInMHPCOsFavor(
192	      applyCustomerModifiers(priceItems(items), customer, isFirstContract),
193	    ) + PROCESSING_FEE,
194	});
195	
196	/**
197	 * Approximates "is this the customer's first contract?" by step position.
198	 *
199	 * This holds only while the first step is a quote. Now that claims interleave
200	 * with quotes, a scenario opening with a claim would make the quote that
201	 * follows look like a repeat contract. No test reaches that yet; when one
202	 * does, this has to count quote steps rather than trust the index.
203	 */
204	const isFirstContractAtStep = (stepIndex: number): boolean => stepIndex === 0;
205	
206	const DEDUCTIBLE = 100;
207	const CAP_MULTIPLE = 2;
208	
209	const insuranceSumOf = (items: InsuredItem[]): number =>
210	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
211	
212	const HEAVILY_ENCHANTED_LEVEL = 8;
213	const HALF = 0.5;
214	const IN_FULL = 1;
215	
216	/** Damage to a heavily enchanted item is only half reimbursed. */
217	const reimbursementRateFor = (item: InsuredItem | undefined): number =>
218	  (item?.enchantment ?? 0) >= HEAVILY_ENCHANTED_LEVEL ? HALF : IN_FULL;
219	
220	const reimbursableAmountOf = (
221	  damage: Damage,
222	  insuredItems: InsuredItem[],
223	): number =>
224	  damage.amount *
225	  reimbursementRateFor(
226	    insuredItems.find((item) => item.type === damage.itemType),
227	  );
228	
229	/** One incident is one deductible, so the damages are totalled before it applies. */
230	const totalDamageOf = (
231	  incident: Incident,
232	  insuredItems: InsuredItem[],
233	): number =>
234	  incident.damages.reduce(
235	    (sum, damage) => sum + reimbursableAmountOf(damage, insuredItems),
236	    0,
237	  );
238	
239	/** The MHPCO never pays a negative claim; below the deductible it pays nothing. */
240	const NO_PAYOUT = 0;
241	
242	/**
243	 * The customer bears the deductible, so only the damage above it is owed —
244	 * and an incident that stays within the deductible is owed nothing rather
245	 * than turning the shortfall into a debt.
246	 */
247	const payoutFor = (incident: Incident, insuredItems: InsuredItem[]): number =>
248	  Math.max(NO_PAYOUT, totalDamageOf(incident, insuredItems) - DEDUCTIBLE);
249	
250	const settleClaim = (
251	  incident: Incident,
252	  insuredItems: InsuredItem[],
253	): ClaimResult => {
254	  const payout = payoutFor(incident, insuredItems);
255	
256	  return {
257	    payout,
258	    remainingCap: CAP_MULTIPLE * insuranceSumOf(insuredItems) - payout,
259	  };
260	};
261	
262	/**
263	 * A claim names the quote step it is made against; the items on that step are
264	 * the ones the policy covers.
265	 */
266	const itemsCoveredBy = (claim: ClaimStep, steps: Step[]): InsuredItem[] => {
267	  const policy = steps[claim.policy];
268	
269	  return policy.op === "quote" ? policy.items : [];
270	};
271	
272	export const runScenario = ({
273	  customer,
274	  steps,
275	}: Scenario): ScenarioResults => ({
276	  results: steps.map((step, stepIndex) =>
277	    step.op === "claim"
278	      ? settleClaim(step.incident, itemsCoveredBy(step, steps))
279	      : quotePremium(step.items, customer, isFirstContractAtStep(stepIndex)),
280	  ),
281	});
